import 'package:flutter/material.dart';\nimport 'package:flutter_riverpod/flutter_riverpod.dart';\nimport 'package:go_router/go_router.dart';\nimport 'package:awesome_dialog/awesome_dialog.dart';\nimport '../providers/auth_provider.dart';\nimport '../widgets/custom_text_field.dart';\nimport '../widgets/custom_button.dart';\n\nclass LoginScreen extends ConsumerStatefulWidget {\n  const LoginScreen({Key? key}) : super(key: key);\n\n  @override\n  ConsumerState<LoginScreen> createState() => _LoginScreenState();\n}\n\nclass _LoginScreenState extends ConsumerState<LoginScreen> {\n  final TextEditingController _emailController = TextEditingController();\n  final TextEditingController _passwordController = TextEditingController();\n  bool _isPasswordVisible = false;\n  bool _isLoading = false;\n\n  @override\n  void dispose() {\n    _emailController.dispose();\n    _passwordController.dispose();\n    super.dispose();\n  }\n\n  void _handleLogin() async {\n    final email = _emailController.text.trim();\n    final password = _passwordController.text.trim();\n\n    if (email.isEmpty || password.isEmpty) {\n      AwesomeDialog(\n        context: context,\n        dialogType: DialogType.error,\n        title: 'Gagal Login',\n        desc: 'Email dan password tidak boleh kosong',\n        btnOkOnPress: () {},\n      ).show();\n      return;\n    }\n\n    setState(() => _isLoading = true);\n\n    try {\n      await ref.read(loginProvider((email, password)).future);\n      if (mounted) {\n        AwesomeDialog(\n          context: context,\n          dialogType: DialogType.success,\n          title: 'Berhasil',\n          desc: 'Login berhasil!',\n          btnOkOnPress: () {\n            context.go('/home');\n          },\n        ).show();\n      }\n    } catch (e) {\n      if (mounted) {\n        AwesomeDialog(\n          context: context,\n          dialogType: DialogType.error,\n          title: 'Gagal Login',\n          desc: e.toString(),\n          btnOkOnPress: () {},\n        ).show();\n      }\n    } finally {\n      if (mounted) setState(() => _isLoading = false);\n    }\n  }\n\n  void _handleGoogleLogin() async {\n    setState(() => _isLoading = true);\n    try {\n      await ref.read(googleLoginProvider.future);\n      if (mounted) {\n        context.go('/home');\n      }\n    } catch (e) {\n      if (mounted) {\n        AwesomeDialog(\n          context: context,\n          dialogType: DialogType.error,\n          title: 'Gagal Login',\n          desc: e.toString(),\n          btnOkOnPress: () {},\n        ).show();\n      }\n    } finally {\n      if (mounted) setState(() => _isLoading = false);\n    }\n  }\n\n  @override\n  Widget build(BuildContext context) {\n    return Scaffold(\n      appBar: AppBar(\n        title: const Text('Masuk'),\n        centerTitle: true,\n      ),\n      body: SafeArea(\n        child: SingleChildScrollView(\n          padding: const EdgeInsets.symmetric(horizontal: 20, vertical: 20),\n          child: Column(\n            crossAxisAlignment: CrossAxisAlignment.start,\n            children: [\n              const SizedBox(height: 20),\n              Text(\n                'Selamat Datang di Hoomly',\n                style: Theme.of(context).textTheme.displaySmall,\n              ),\n              const SizedBox(height: 8),\n              Text(\n                'Masuk dengan akun Anda untuk melanjutkan',\n                style: Theme.of(context).textTheme.bodyMedium,\n              ),\n              const SizedBox(height: 40),\n              CustomTextField(\n                controller: _emailController,\n                label: 'Email',\n                hint: 'Masukkan email Anda',\n                keyboardType: TextInputType.emailAddress,\n                prefixIcon: const Icon(Icons.email_outlined),\n              ),\n              const SizedBox(height: 16),\n              CustomTextField(\n                controller: _passwordController,\n                label: 'Password',\n                hint: 'Masukkan password Anda',\n                isPassword: true,\n                isPasswordVisible: _isPasswordVisible,\n                onPasswordVisibilityChanged: (value) {\n                  setState(() => _isPasswordVisible = value);\n                },\n                prefixIcon: const Icon(Icons.lock_outline),\n              ),\n              const SizedBox(height: 12),\n              Align(\n                alignment: Alignment.centerRight,\n                child: TextButton(\n                  onPressed: () => context.push('/forgot-password'),\n                  child: const Text('Lupa Password?'),\n                ),\n              ),\n              const SizedBox(height: 20),\n              CustomButton(\n                text: 'Masuk',\n                isLoading: _isLoading,\n                onPressed: _handleLogin,\n              ),\n              const SizedBox(height: 20),\n              Row(\n                children: const [\n                  Expanded(child: Divider()),\n                  Padding(\n                    padding: EdgeInsets.symmetric(horizontal: 12),\n                    child: Text('atau'),\n                  ),\n                  Expanded(child: Divider()),\n                ],\n              ),\n              const SizedBox(height: 20),\n              SizedBox(\n                width: double.infinity,\n                height: 50,\n                child: OutlinedButton(\n                  onPressed: _isLoading ? null : _handleGoogleLogin,\n                  child: Row(\n                    mainAxisAlignment: MainAxisAlignment.center,\n                    children: [\n                      Image.network(\n                        'https://www.google.com/favicon.ico',\n                        width: 20,\n                        height: 20,\n                      ),\n                      const SizedBox(width: 12),\n                      const Text('Masuk dengan Google'),\n                    ],\n                  ),\n                ),\n              ),\n              const SizedBox(height: 20),\n              Row(\n                mainAxisAlignment: MainAxisAlignment.center,\n                children: [\n                  const Text('Belum punya akun? '),\n                  TextButton(\n                    onPressed: () => context.push('/register'),\n                    child: const Text('Daftar di sini'),\n                  ),\n                ],\n              ),\n            ],\n          ),\n        ),\n      ),\n    );\n  }\n}\n